def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()

    # Find full single-colour lines (rows or columns).
    d = dividers(g)
    lines = []  # (axis, index, colour); axis 0 = row line, 1 = column line
    for y, c in d["rows"]:
        if c != bg:
            lines.append((0, y, c))
    for x, c in d["cols"]:
        if c != bg:
            lines.append((1, x, c))
    line_colours = {c for _, _, c in lines}

    # Dots: non-background cells that are not part of a line.
    dots = [(y, x) for y in range(H) for x in range(W)
            if g[y, x] != bg and g[y, x] not in line_colours]

    # Assign each dot to its nearest line.
    assign = {}
    for (y, x) in dots:
        best = None
        for axis, idx, c in lines:
            dist = abs(y - idx) if axis == 0 else abs(x - idx)
            if best is None or dist < best[0]:
                best = (dist, c)
        if best is not None:
            assign[(y, x)] = best[1]

    # Recolour stage by stage, one line colour at a time.
    for axis, idx, c in lines:
        changed = False
        for (y, x), col in assign.items():
            if col == c and out[y, x] != c:
                out[y, x] = c
                changed = True
        if changed:
            emit(out, f"Recolour every dot whose nearest line is the colour-{c} line to {c}.")

    emit(out, "All dots now carry the colour of their nearest border line.")
    return out
